import{logger}from './logger.js';let imagesData={images: [],categories:{}};let selectedFile=null;let currentImagesList=[];let currentImageIndex=0;let currentCategory='all';document.addEventListener('DOMContentLoaded',function(){initializeGallery();setupUpload();});async function initializeGallery(){await loadImages();populateCategories();displayImages('all');}function setupUpload(){const uploadArea=document.getElementById('uploadArea');const fileInput=document.getElementById('fileInput');uploadArea.addEventListener('dragover',(e)=>{e.preventDefault();uploadArea.classList.add('dragover');});uploadArea.addEventListener('dragleave',()=>{uploadArea.classList.remove('dragover');});uploadArea.addEventListener('drop',(e)=>{e.preventDefault();uploadArea.classList.remove('dragover');handleFileSelection(e.dataTransfer.files[0]);});fileInput.addEventListener('change',(e)=>{handleFileSelection(e.target.files[0]);});}function handleFileSelection(file){if(!file)return;const validTypes=['image/png','image/jpeg','image/jpg','application/pdf'];if(!validTypes.includes(file.type)){showStatus('Seuls les fichiers PNG,JPG et PDF sont acceptés','error');return;}const maxSize=5*1024*1024;if(file.size>maxSize){showStatus('Le fichier est trop volumineux(max 5MB)','error');return;}selectedFile=file;showFilePreview(file);document.getElementById('metadataForm').style.display='block';}function showFilePreview(file){const existingPreview=document.querySelector('.file-preview');if(existingPreview){existingPreview.remove();}const preview=document.createElement('div');preview.className='file-preview';if(file.type.startsWith('image/')){const reader=new FileReader();reader.onload=function(e){preview.innerHTML=`<img src="${e.target.result}" alt="Aperçu"><div><strong>${file.name}</strong><br><small>${(file.size/1024).toFixed(1)}KB • ${file.type.split('/')[1].toUpperCase()}</small></div><button onclick="removeFilePreview()" style="margin-left: auto;background: #dc3545;color: white;border: none;border-radius: 4px;padding: 0.5rem;">✖</button>`;};reader.readAsDataURL(file);}else{preview.innerHTML=`<div class="pdf-icon">📄</div><div><strong>${file.name}</strong><br><small>${(file.size/1024).toFixed(1)}KB • PDF</small></div><button onclick="removeFilePreview()" style="margin-left: auto;background: #dc3545;color: white;border: none;border-radius: 4px;padding: 0.5rem;">✖</button>`;}document.getElementById('metadataForm').prepend(preview);}function removeFilePreview(){selectedFile=null;const preview=document.querySelector('.file-preview');if(preview)preview.remove();document.getElementById('metadataForm').style.display='none';document.getElementById('fileInput').value='';resetForm();}async function uploadImage(){if(!selectedFile){showStatus('Aucun fichier sélectionné','error');return;}const category=document.getElementById('categorySelect').value;const subcategory=document.getElementById('subcategoryInput').value.trim();const title=document.getElementById('titleInput').value.trim();const description=document.getElementById('descriptionInput').value.trim();const tagsInput=document.getElementById('tagsInput').value.trim();if(!category||!title){showStatus('Veuillez remplir au minimum la catégorie et le titre','error');return;}const formData=new FormData();formData.append('file',selectedFile);formData.append('category',category);formData.append('subcategory',subcategory);formData.append('title',title);formData.append('description',description);formData.append('tags',tagsInput);try{showStatus('Upload en cours...','info');const response=await fetch('/api/upload_image',{method: 'POST',body: formData});const result=await response.json();if(response.ok&&result.success){showStatus('✅ Image uploadée avec succès!','success');resetUploadForm();await loadImages();displayImages('all');}else{showStatus(`❌ Erreur : ${result.error||'Erreur inconnue'}`,'error');}}catch(error){showStatus(`❌ Erreur de connexion : ${error.message}`,'error');logger.error('Erreur upload:',error);}}async function loadImages(){try{const response=await fetch('/src/data/images_metadata.json');if(response.ok){imagesData=await response.json();}else{imagesData={images: [],categories:{"anatomie-physiologie":{name: "Anatomie&Physiologie",icon: "🫀",description: "Schémas anatomiques et mécanismes physiologiques"},"systemes":{name: "Systèmes&Processus",icon: "⚙️",description: "Processus pathologiques et systémiques"},"normes":{name: "Normes&Protocoles",icon: "📋",description: "Valeurs de référence et protocoles de soins"}}};}}catch(error){logger.info('Première utilisation-aucune image encore uploadée');imagesData={images: [],categories:{"anatomie-physiologie":{name: "Anatomie&Physiologie",icon: "🫀",description: "Schémas anatomiques et mécanismes physiologiques"},"systemes":{name: "Systèmes&Processus",icon: "⚙️",description: "Processus pathologiques et systémiques"},"normes":{name: "Normes&Protocoles",icon: "📋",description: "Valeurs de référence et protocoles de soins"}}};}}function populateCategories(){}function safeGetElement(id){const element=document.getElementById(id);if(!element){logger.warn(`Élément ${id}non trouvé dans le DOM`);return null;}return element;}function displayImages(categoryFilter){const grid=safeGetElement('imagesGrid');if(!grid)return;let filteredImages=imagesData.images;if(categoryFilter!=='all'){filteredImages=imagesData.images.filter(img=>img.category===categoryFilter);}if(filteredImages.length===0){grid.innerHTML=`<div class="empty-state"><div class="empty-state-icon">🖼️</div><h4>Aucune image dans cette catégorie</h4><p>Commencez par uploader votre première image!</p></div>`;return;}grid.innerHTML=filteredImages.map(img=>`<div class="image-card"><div class="image-thumbnail" onclick="viewImageInModal('images/${img.category}/${img.filename}',${JSON.stringify(img).replace(/"/g,'&quot;')})" style="cursor: pointer;">${img.type==='pdf' ? '<div class="pdf-thumbnail">📄</div>' : `<img src="images/${img.category}/${img.filename}" alt="${img.description}">`}</div><div class="image-info"><h4>${img.title||img.description}</h4><div class="image-meta">${imagesData.categories[img.category]?.icon||'📁'}${imagesData.categories[img.category]?.name||img.category}${img.subcategory ? ` • ${img.subcategory}` : ''}<br>📅 ${img.uploaded_date}• 📏 ${img.size}</div>${img.tags&&img.tags.length>0 ? `<div class="image-tags">${img.tags.map(tag=>`<span class="tag">${tag}</span>`).join('')}</div>` : ''}<div class="image-actions"><button class="action-btn view-btn" onclick="viewImageInModal('images/${img.category}/${img.filename}',${JSON.stringify(img).replace(/"/g,'&quot;')})">👁️ Voir</button><button class="action-btn download-btn" onclick="downloadImage('${img.id}')">⬇️ Télécharger</button></div></div></div>`).join('');addAdminButtonsToImages();}function addAdminButtonsToImages(){if(typeof authManager!=='undefined'&&authManager.isAdmin()){document.querySelectorAll('.image-card').forEach((card,index)=>{const actionsDiv=card.querySelector('.image-actions');if(actionsDiv&&!actionsDiv.querySelector('.delete-btn')){const img=getCurrentFilteredImages()[index];if(img){const deleteBtn=document.createElement('button');deleteBtn.className='action-btn delete-btn';deleteBtn.innerHTML='🗑️ Supprimer';deleteBtn.onclick=()=>deleteImage(`images/${img.category}/${img.filename}`,img);actionsDiv.appendChild(deleteBtn);}}});}}function getCurrentFilteredImages(){const activeTab=document.querySelector('.category-tab.active');if(!activeTab)return imagesData.images;const categoryFilter=activeTab.onclick.toString().match(/showCategory\('(.+?)'\)/);const category=categoryFilter ? categoryFilter[1] : 'all';if(category==='all'){return imagesData.images;}else{return imagesData.images.filter(img=>img.category===category);}}function showCategory(category){document.querySelectorAll('.category-tab').forEach(tab=>{tab.classList.remove('active');});event.target.classList.add('active');displayImages(category);}function viewImage(imageId){const image=imagesData.images.find(img=>img.id===imageId);if(!image)return;const imageUrl=`images/${image.category}/${image.filename}`;if(image.type==='pdf'){window.open(imageUrl,'_blank');}else{showImageModal(image,imageUrl);}}function showImageModal(image,imageUrl){const modal=document.createElement('div');modal.style.cssText=` position: fixed;top: 0;left: 0;width: 100%;height: 100%;background: rgba(0,0,0,0.9);display: flex;align-items: center;justify-content: center;z-index: 1000;cursor: pointer;`;modal.innerHTML=`<div style="max-width: 90%;max-height: 90%;text-align: center;"><img src="${imageUrl}" alt="${image.description}" style="max-width: 100%;max-height: 80vh;border-radius: 8px;"><div style="color: white;padding: 1rem;background: rgba(0,0,0,0.7);border-radius: 8px;margin-top: 1rem;"><h3>${image.description}</h3><p>${image.subcategory ? image.subcategory+' • ' : ''}${image.uploaded_date}</p></div></div>`;modal.addEventListener('click',()=>{document.body.removeChild(modal);});document.body.appendChild(modal);}function downloadImage(imageId){const image=imagesData.images.find(img=>img.id===imageId);if(!image)return;const imageUrl=`images/${image.category}/${image.filename}`;const link=document.createElement('a');link.href=imageUrl;link.download=image.original_name||image.filename;document.body.appendChild(link);link.click();document.body.removeChild(link);}function resetUploadForm(){selectedFile=null;document.getElementById('metadataForm').style.display='none';document.getElementById('fileInput').value='';resetForm();const preview=document.querySelector('.file-preview');if(preview)preview.remove();}function resetForm(){document.getElementById('categorySelect').value='';document.getElementById('subcategoryInput').value='';document.getElementById('titleInput').value='';document.getElementById('descriptionInput').value='';document.getElementById('tagsInput').value='';}function showStatus(message,type){const statusDiv=document.getElementById('status');statusDiv.textContent=message;statusDiv.className=`status ${type}`;setTimeout(()=>{statusDiv.textContent='';statusDiv.className='';},5000);}document.addEventListener('keydown',function(event){if(event.key==='Escape'){const modal=document.querySelector('[style*="position: fixed"]');if(modal){document.body.removeChild(modal);}closeImageModal();cancelDelete();}});let imageToDelete=null;function viewImageInModal(imagePath,imageData){const activeTab=document.querySelector('.category-tab.active');let currentCategory='all';if(activeTab){if(activeTab.dataset.category){currentCategory=activeTab.dataset.category;}else{const categoryMatch=activeTab.onclick.toString().match(/showCategory\('(.+?)'\)/);currentCategory=categoryMatch ? categoryMatch[1] : 'all';}}if(currentCategory==='all'){currentImagesList=imagesData.images;}else{currentImagesList=imagesData.images.filter(img=>img.category===currentCategory);}currentImageIndex=currentImagesList.findIndex(img=>`images/${img.category}/${img.filename}`===imagePath);if(currentImageIndex===-1){currentImageIndex=currentImagesList.findIndex(img=>img.id===imageData.id);}const modal=document.getElementById('imageModal');const modalImage=document.getElementById('modalImage');const modalTitle=document.getElementById('modalTitle');const modalDescription=document.getElementById('modalDescription');const modalDescriptionContainer=document.getElementById('modalDescriptionContainer');const modalInfo=document.getElementById('modalInfo');modalInfo.classList.remove('hidden');modalImage.src=imagePath;modalTitle.textContent=imageData.title||imageData.description||imageData.filename;modalDescription.textContent=imageData.description||'Aucune description disponible';modalDescriptionContainer.style.display='none';const toggleButton=document.getElementById('descriptionToggle');toggleButton.textContent='📝 Afficher description';toggleButton.classList.remove('hide');toggleButton.classList.add('show');modal.style.display='flex';document.body.style.overflow='hidden';}function closeImageModal(){const modal=document.getElementById('imageModal');const modalInfo=document.getElementById('modalInfo');modal.style.display='none';modalInfo.classList.add('hidden');document.body.style.overflow='auto';}function toggleDescription(){const descriptionContainer=document.getElementById('modalDescriptionContainer');const toggleButton=document.getElementById('descriptionToggle');if(descriptionContainer.style.display==='none'){descriptionContainer.style.display='block';toggleButton.textContent='📝 Masquer description';toggleButton.classList.remove('show');toggleButton.classList.add('hide');}else{descriptionContainer.style.display='none';toggleButton.textContent='📝 Afficher description';toggleButton.classList.remove('hide');toggleButton.classList.add('show');}}function previousImage(){if(currentImagesList.length===0)return;currentImageIndex=currentImageIndex>0 ? currentImageIndex-1 : currentImagesList.length-1;const currentImage=currentImagesList[currentImageIndex];const modalImage=document.getElementById('modalImage');const modalTitle=document.getElementById('modalTitle');const modalDescription=document.getElementById('modalDescription');const modalDescriptionContainer=document.getElementById('modalDescriptionContainer');modalImage.src=`images/${currentImage.category}/${currentImage.filename}`;modalTitle.textContent=currentImage.title||currentImage.description||currentImage.filename;modalDescription.textContent=currentImage.description||'Aucune description disponible';modalDescriptionContainer.style.display='none';const toggleButton=document.getElementById('descriptionToggle');toggleButton.textContent='📝 Afficher description';toggleButton.classList.remove('hide');toggleButton.classList.add('show');}function nextImage(){if(currentImagesList.length===0)return;currentImageIndex=currentImageIndex<currentImagesList.length-1 ? currentImageIndex+1 : 0;const currentImage=currentImagesList[currentImageIndex];const modalImage=document.getElementById('modalImage');const modalTitle=document.getElementById('modalTitle');const modalDescription=document.getElementById('modalDescription');const modalDescriptionContainer=document.getElementById('modalDescriptionContainer');modalImage.src=`images/${currentImage.category}/${currentImage.filename}`;modalTitle.textContent=currentImage.title||currentImage.description||currentImage.filename;modalDescription.textContent=currentImage.description||'Aucune description disponible';modalDescriptionContainer.style.display='none';const toggleButton=document.getElementById('descriptionToggle');toggleButton.textContent='📝 Afficher description';toggleButton.classList.remove('hide');toggleButton.classList.add('show');}function deleteImage(imagePath,imageData){imageToDelete={path: imagePath,data: imageData};const deleteConfirm=safeGetElement('deleteConfirm');const deleteImageName=safeGetElement('deleteImageName');if(deleteConfirm&&deleteImageName){deleteImageName.textContent=imageData.description||imageData.filename;deleteConfirm.style.display='flex';document.body.style.overflow='hidden';}}function cancelDelete(){const deleteConfirm=document.getElementById('deleteConfirm');deleteConfirm.style.display='none';document.body.style.overflow='auto';imageToDelete=null;}async function confirmDelete(){if(!imageToDelete)return;try{const response=await fetch('/api/delete_image',{method: 'DELETE',headers:{'Content-Type': 'application/json'},body: JSON.stringify({imagePath: imageToDelete.path})});const result=await response.json();if(result.success){showStatus('Image supprimée avec succès','success');cancelDelete();await loadImages();const activeTab=document.querySelector('.category-tab.active');const category=activeTab.dataset.category||activeTab.onclick.toString().match(/showCategory\('(.+?)'\)/)[1];displayImages(category);}else{showStatus('Erreur lors de la suppression: '+result.error,'error');}}catch(error){logger.error('Erreur suppression:',error);showStatus('Erreur lors de la suppression','error');}}function searchImages(){const searchTerm=document.getElementById('searchInput').value.toLowerCase().trim();const clearButton=document.querySelector('.clear-search');if(searchTerm){clearButton.style.display='block';}else{clearButton.style.display='none';}if(searchTerm){const filteredImages=imagesData.images.filter(img=>{const title=(img.title||img.description||'').toLowerCase();return title.includes(searchTerm);});displayFilteredImages(filteredImages,`Résultats de recherche pour "${document.getElementById('searchInput').value}"`);document.querySelectorAll('.category-tab').forEach(tab=>{tab.classList.remove('active');});}else{showCategory('all');}}function clearSearch(){document.getElementById('searchInput').value='';document.querySelector('.clear-search').style.display='none';showCategory('all');}function displayFilteredImages(filteredImages,title){const grid=document.getElementById('imagesGrid');if(filteredImages.length===0){grid.innerHTML=`<div class="empty-state"><div class="empty-state-icon">🔍</div><h4>Aucun résultat trouvé</h4><p>Essayez avec d'autres mots-clés</p></div>`;return;}grid.innerHTML=filteredImages.map(img=>`<div class="image-card"><div class="image-thumbnail" onclick="viewImageInModal('images/${img.category}/${img.filename}',${JSON.stringify(img).replace(/"/g,'&quot;')})" style="cursor: pointer;">${img.type==='pdf' ? '<div class="pdf-thumbnail">📄</div>' : `<img src="images/${img.category}/${img.filename}" alt="${img.description}">`}</div><div class="image-info"><h4>${img.title||img.description}</h4><div class="image-meta">${imagesData.categories[img.category]?.icon||'📁'}${imagesData.categories[img.category]?.name||img.category}${img.subcategory ? ` • ${img.subcategory}` : ''}<br>📅 ${img.uploaded_date}• 📏 ${img.size}</div>${img.tags&&img.tags.length>0 ? `<div class="image-tags">${img.tags.map(tag=>`<span class="tag">${tag}</span>`).join('')}</div>` : ''}<div class="image-actions"><button class="action-btn view-btn" onclick="viewImageInModal('images/${img.category}/${img.filename}',${JSON.stringify(img).replace(/"/g,'&quot;')})">👁️ Voir</button><button class="action-btn download-btn" onclick="downloadImage('${img.id}')">⬇️ Télécharger</button></div></div></div>`).join('');}